  const project = await request(`/api/projects/${match[1]}`);
  if (activeProjectId !== match[1]) {
    taskFilter.value = 'All';
    priorityFilter.value = 'All';
    appliedDueRange = { from: '', through: '' };
    dueFromInput.value = '';
    dueThroughInput.value = '';
